"""Write the baseline review pack: docs/baseline/SDEM-METAMODEL-0.8-review-pack.md.

A point-in-time snapshot for an independent reviewer (not regenerated by CI): what is being baselined, the evidence,
the known limitations, the review checklist and the sign-off. All counts are computed from the records when run.
Usage: python scripts/baseline_pack.py
"""
import glob, json, subprocess, sys
from collections import Counter
from datetime import date
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from sdem.conformance import check_level, estate_index  # noqa: E402
from sdem.metamodel import Metamodel  # noqa: E402
from sdem.validate import check_schema  # noqa: E402

BASELINE = 'SDEM-METAMODEL-0.8'
OUT = ROOT / 'docs' / 'design' / 'baseline' / f'{BASELINE}-review-pack.md'


def J(p): return json.loads((ROOT / p).read_text(encoding='utf-8'))


def hml(xs, key='confidence'):
    c = Counter(x.get(key) for x in xs); return c['high'], c['medium'], c['low']


def tests():
    r = subprocess.run([sys.executable, '-m', 'unittest', 'discover', '-s', 'tests'], cwd=ROOT, capture_output=True, text=True)
    ran = next((l for l in r.stderr.splitlines() if l.startswith('Ran ')), 'Ran ? tests'); return ran.split()[1], r.stderr.strip().splitlines()[-1]


def conformance(mm):
    err = warn = inst = 0; schemas = {json.loads(Path(p).read_text())['title']: json.loads(Path(p).read_text()) for p in glob.glob(str(ROOT / 'schema/entities/*/*.schema.json'))}; bad = 0
    for est in sorted(glob.glob(str(ROOT / 'examples' / '*') + '/')):
        docs = [json.loads(Path(f).read_text()) for f in sorted(glob.glob(est + 'a[1-4]-*.json'))]; idx = estate_index(docs)
        for d in docs:
            e, w, _ = check_level(d, mm, idx); err += len(e); warn += len(w); inst += len(d['instances'])
            bad += sum(1 for i in d['instances'] if check_schema(i, schemas[i['type']]))
    return len(glob.glob(str(ROOT / 'examples' / '*') + '/')), inst, err, warn, len(schemas), bad


def main():
    mm = Metamodel.load()
    ents = [e for f in sorted(glob.glob(str(ROOT / 'metamodel/a[1-4]-*.json'))) for e in json.loads(Path(f).read_text())['entities']]
    lr = J('metamodel/level-relationships.json'); rows = lr['constraints']
    types = J('schema/relationship-types.json')['relationships']; rules = J('metamodel/relationship-rules.json')['mappings']
    at = J('metamodel/entity-attributes.json'); attrs = [a for a in at['attributes'] if a['status'] == 'active']; common = at['common_attributes']; derived = at.get('derived_attributes', [])
    dep = [a for a in at['attributes'] if a['status'] == 'deprecated']
    gaps = J('metamodel/metamodel-spec-gaps.json')['gaps']
    gopen = [g for g in gaps if g['status'].startswith('open')]; gdec = [g for g in gaps if g['status'].startswith('decided')]
    import hashlib
    hsha = hashlib.sha256((ROOT / 'docs' / 'design' / 'architecture-metamodel-high-level-spec.md').read_bytes()).hexdigest()
    cases = J('examples/acceptance-cases.json')['cases']; passing = sum(1 for c in cases if c.get('engine_status') == 'passing')
    ntests, tline = tests(); est, inst, err, warn, nschema, schema_bad = conformance(mm)
    ver = Counter(c['verification'] for c in rows)
    low_rows = [c for c in rows if c['confidence'] == 'low']
    lows = [f"`{a['entity']}.{a['name']}`" for a in attrs if a['confidence'] == 'low']
    gated = [e['type'] for e in ents if e.get('definition_source') == 'togaf_informed'] + [c['id'] for c in rows if c['verification'] == 'unverified_togaf'] + [f"{a['entity']}.{a['name']}" for a in attrs if a['source'] == 'TOGAF']
    items = ents + rows + types + attrs + common + at['core_fields']
    H, M, L = hml(items); N = H + M + L
    o = [f'# {BASELINE} — Baseline Review Pack', '',
         f'> Prepared {date.today().isoformat()} by `python scripts/baseline_pack.py` from the records at commit `{subprocess.run(["git", "rev-parse", "--short", "HEAD"], cwd=ROOT, capture_output=True, text=True).stdout.strip()}`. A snapshot for review, not a living document.', '',
         '## 1. What a baseline is, and what you are asked to approve', '',
         f'A **baseline** freezes one reviewed version of the SDEM blueprint under a name, **{BASELINE}**. Tool adapters build against it, approved relationship records point to it, and later changes are made as new versions with a change log. Approving it means: *the model is fit to receive real architecture data, and its sources, reasoning and confidence ratings are credible.* It does not mean every rating is high — the limitations in §4 are part of what is approved.', '',
         '**What to review against.** The governing specification is [`architecture-metamodel-detail-level-spec.md`](../architecture-metamodel-detail-level-spec.md) (with its diagram `architecture-metamodel-detail-level-spec.puml`). It follows the owner\'s high-level specification section by section — [`architecture-metamodel-high-level-spec.md`](../architecture-metamodel-high-level-spec.md), the frozen reference — and records every difference in its gap register. Review the detail spec; use the high-level spec to judge whether the differences are acceptable.', '',
         '**Who should review.** An architect independent of the author, familiar with at least one of BIAN, ArchiMate or TOGAF. They need no employer data: everything here is public or synthetic. Expected effort: about a day for §5, longer if they re-check sources.', '',
         '## 2. What is being baselined', '',
         '| Part | Records | Count | Rendered as |', '|---|---|---|---|',
         f"| **Governing specification** | generated from all records below | 19 sections, data model of every part, gap register ({len(gaps)} gaps: {len(gdec)} decided, {len(gopen)} open) | `docs/design/architecture-metamodel-detail-level-spec.md` (+ `.puml`) |",
         f"| Reference specification (frozen) | — | the owner\'s v0.4 spec, SHA-256 `{hsha[:16]}…` pinned by test | `docs/design/architecture-metamodel-high-level-spec.md` |",
         f"| Entity types | `metamodel/a1…a4-*.json` | {len(ents)} ({sum(1 for e in ents if not e.get('abstract') and not e.get('artefact'))} instance types, {sum(1 for e in ents if e.get('artefact'))} artefacts, {sum(1 for e in ents if e.get('abstract'))} abstract) | `docs/reference/architecture-entity-design.md` |",
         f"| Within-level relationships | `metamodel/level-relationships.json` | {len(rows)} rows + {len(lr['inheritance'])} inheritance | `docs/reference/relationships-planning.md` |",
         f"| Cross-level relationship types | `schema/relationship-types.json` | {len(types)} | `docs/design/relationship-registry-spec.md` |",
         f"| Relationship rules | `metamodel/relationship-rules.json` | {len(rules)} | `docs/design/relationship-rules-spec.md` |",
         f"| Attributes | `metamodel/entity-attributes.json` | {len(at['core_fields'])} core, {len(common)} common, {len(attrs)} entity-specific, {len(derived)} derived ({len(dep)} deprecated kept for compatibility) | `docs/reference/architecture-attribute-design.md` |",
         '| Logical data model | `sdem/logical.py`, `sdem/conformance.py` | 14 rules, all enforced | `docs/reference/logical-data-model.md` |',
         f"| Physical data model | `schema/entities/*/*.schema.json` | {nschema} JSON Schemas | `docs/reference/physical-data-model.md` |",
         '| Data-model review records | `metamodel/drafts/a1…a4-descriptive-attributes.json` | 4 (all approved) | `docs/drafts/data-model-a1…a4-draft.md` |', '',
         'Not in scope: the inference engine and the graph store (software built on the metamodel; their test results are evidence in §3, but the baseline freezes the metamodel, not the code), the Relationship Registry contents (institution data), and the example estates (synthetic test data).', '',
         '## 3. Evidence', '',
         '| Check | Result |', '|---|---|',
         f"| Unit tests | {ntests} tests — {tline} |",
         f"| Example estates against the enforced data model (`sdem-graph check`) | {est} estates, {inst} instances: **{err} errors**, {warn} warnings, all minimum-cardinality completeness gaps (an example, or the generated reference-structure estate, holds part of BIAN's structure) |",
         f"| Example instances against the physical schemas | {inst} instances, **{schema_bad} failing** |",
         f"| Within-level rows checked against a standard | {ver['verified']} against BIAN public material, {ver['verified_against_archi']} against the Archi oracle (open-source ArchiMate relationship tables); {ver['unverified_togaf']} TOGAF-only, {ver['sdem_reading']} SDEM reading |",
         '| Cross-level rules | all 69 plan rows covered by the use-case runs: 45 validated, 5 validated with findings, 19 not applicable (`docs/evidence/relationships-testing.md`, `docs/evidence/use-case-testing.md`) |',
         '| Detail spec against the high-level spec | catalogue alignment computed from the high-level §5 tables: 41 entity rows read, 1 differs (`A4.Deployment`, decided G-03); every other difference is in the gap register; the high-level spec is unchanged (checksum test) |',
         f"| Inference engine (acceptance) | {passing} of {len(cases)} use-case runs pass at the hand-executed run\'s precision and recall or better (`sdem-accept`); every proposal validates |",
         '| Graph store | every trace and impact answer identical whether read from the stored graph or the architecture datasets, on all example estates (acceptance test AT-04) |',
         '| Source references | every entity, row, type, rule and attribute names its source; enforced by test |',
         '| Confidence | one rule (`sdem/confidence.py`) assigns every rating; CI fails if any record disagrees |',
         '| Generated documents | every document and schema is generated from the records; CI fails if any is stale |', '',
         f"**Confidence across {N} rated definitions** (entities, within-level rows, relationship types, core, common and entity-specific attributes): **{H} high ({round(100*H/N)}%), {M} medium ({round(100*M/N)}%), {L} low ({round(100*L/N)}%)**. High = defined by a public standard and checked; medium = built on a standard concept, or a standard that could not be checked; low = SDEM-defined with no standard basis.", '',
         '| Layer | High | Medium | Low |', '|---|---|---|---|']
    for name, xs in (('Entity types', ents), ('Within-level rows', rows), ('Relationship types', types), ('Core fields', at['core_fields']), ('Common attributes', common),
                     ('A1 attributes', [a for a in attrs if a['entity'].startswith('A1')]), ('A2 attributes', [a for a in attrs if a['entity'].startswith('A2')]),
                     ('A3 attributes', [a for a in attrs if a['entity'].startswith('A3')]), ('A4 attributes', [a for a in attrs if a['entity'].startswith('A4')])):
        h, m, l = hml(xs); o.append(f'| {name} | {h} | {m} | {l} |')
    h, m, l = hml(rules, 'basis_confidence'); o.append(f'| Relationship rules (basis; {len(rules) - h - m - l} rows n/a — not used: not encodable or a historical method) | {h} | {m} | {l} |')
    o += ['', '## 4. Known limitations (approved as part of the baseline)', '',
          f"1. **Login-gated standards not checked.** TOGAF and the ArchiMate specification text need an Open Group login. Affected: {', '.join(f'`{g}`' for g in gated)}. ArchiMate relationships were checked against the open-source Archi implementation instead.",
          '2. **BIAN below A2.** BIAN publishes no capability-to-Service-Domain mapping and almost nothing below A2, so most cross-level rules are SDEM\'s design, validated by the use cases rather than by a standard.',
          '3. **BIAN portal Service Domain pages** returned "not found" during the A2 review; no attribute rests on them. The HTTP-method default (DV-A2-02) rests partly on BIAN\'s published API files, not yet checked (medium).',
          '4. **ISO 3166** could not be opened (iso.org 403); `country` is medium.',
          f"5. **{len(lows)} SDEM-defined (low) attributes** — kept deliberately because they answer frequent design questions no open standard covers: " + ', '.join(lows) + '.',
          *([f"6. **{len(low_rows)} within-level row(s) resting on an SDEM reading** with no standard relationship: " + ', '.join(f"`{c['id']}` ({c['source_type']} {c['kind']} {c['target_type']})" for c in low_rows) + '.'] if low_rows else []),
          *[f"{6 + bool(low_rows) + n}. **Open gap {g['id']}** ({g['high_level_section']}): {g['implemented']} Recommendation: {g['recommendation']}" for n, g in enumerate(gopen)],
          f"{6 + bool(low_rows) + len(gopen)}. **Not built from the high-level spec:** Bank Architecture Profiles (G-08) and the BIAN verification register (G-09); BIAN canonical-id checks stay `unverified` without a licensed resolver (G-10).",
          f"{7 + bool(low_rows) + len(gopen)}. **The engine has not met unseen data.** Its decisions DEC-E-07…09 were chosen while the use-case answer keys were known, so passing them shows it follows the procedure, not that it generalises; a blind case (OPEN-05) is the real test.",
          f"{8 + bool(low_rows) + len(gopen)}. **Licensed BIAN validation** has not been done (needs BIAN membership).",
          f"{9 + bool(low_rows) + len(gopen)}. **No real data yet.** Everything has been exercised on synthetic estates only; the first adapter on real data may find gaps.", '',
          '## 5. Review checklist', '',
          'Answer each with **yes / no / comment**. A "no" on 1–8 blocks the baseline; others can be accepted as findings. "Detail §n" means a section of the detail-level spec.', '',
          '| # | Question | Where to look |', '|---|---|---|',
          '| 1 | Does the detail spec follow the high-level spec faithfully, and is every difference either aligned or a recorded gap? | detail spec, each section\'s alignment line; high-level spec |',
          '| 2 | Are the owner\'s gap decisions acceptable — in particular within-level relationships brought into scope (G-01) and derived paths as candidate reports (G-07)? | detail spec, gap register |',
          '| 3 | Are the entity types the right set for business, BIAN service domain, application and technology architecture — nothing essential missing, nothing redundant? | detail §5 |',
          '| 4 | Do the within-level relationships reflect BIAN and ArchiMate as you understand them? Spot-check ten rows against the cited source. | detail §6.1, `relationships-planning.md` |',
          '| 5 | Are the nine cross-level relationship types meaningful and distinct, and is the mapping record (fields, lifecycle, immutability) sound? | detail §6.2, §6.4 |',
          '| 6 | Spot-check ten attributes rated **high**: does the cited section really define that attribute? | `architecture-attribute-design.md` |',
          '| 7 | Is any entity or attribute rated or marked higher than its source justifies (see the open gap on evidence status)? | detail §3, §17 |',
          '| 8 | Is there any sign of proprietary content (BIAN or Open Group text reproduced, employer entities or IDs)? | all documents |',
          '| 9 | Are the low (SDEM-defined) attributes worth keeping? | §4 item 5 |',
          '| 10 | Are the required/optional choices sensible (almost everything optional)? | detail §16, `physical-data-model.md` |',
          '| 11 | Are derived attributes (criticality, HTTP method default) the right choice over stored ones? | `architecture-attribute-design.md` §4 |',
          '| 12 | Do the 14 logical rules make sense as errors vs warnings? | `logical-data-model.md` |',
          '| 13 | Is the mapping rule record (detail §15a) clear enough that someone else could apply the rules? | detail §15a, `mapping-execution.md` |',
          '| 14 | Could an adapter author build an exporter from the physical schemas alone? | `schema/entities/` |',
          '| 15 | Are the limitations in §4 acceptable for a first baseline? | §4 |', '',
          '## 6. Sign-off', '',
          '| Role | Name | Decision (approve / approve with findings / reject) | Date |', '|---|---|---|---|',
          '| Model owner | Steven Taumoepeau | | |', '| Independent reviewer | | | |', '',
          '', '**Note on "generated documents".** CI proves each document matches what its generator produces from the records; it cannot prove the wording inside the records is current. Wording was reviewed by reading all of `docs/` on 2026-10-25.', '',
          'Findings: record each as a GitHub issue labelled `baseline-0.8` and list them here.', '',
          '## 7. On approval', '',
          '0. Resolve or explicitly accept every open gap (' + ', '.join(g['id'] for g in gopen) + ') and record the decision in `metamodel/metamodel-spec-gaps.json`.' if gopen else '0. No open gaps.',
          f'1. Record the approval in `metamodel/baseline.json` (baseline name, commit, reviewer, date, accepted findings).',
          '2. Set `metamodel_version` to `0.8.0` in the four level files and the example architecture datasets.',
          '3. Remove what was kept only for compatibility: the deprecated `accesses` attribute definition and the `sdmm_extension` spelling (the `sdmm` package and commands were removed before the baseline, in the 2026-10-29 audit).',
          f'4. Tag the commit `{BASELINE}` and publish release v0.8.0 (with your approval).',
          '5. From then on, model changes go through a change record and a new version.', '']
    OUT.parent.mkdir(parents=True, exist_ok=True); from sdem.docmap import relink; OUT.write_text(relink('\n'.join(o) + '\n', OUT), encoding='utf-8'); print('wrote', OUT.relative_to(ROOT))


if __name__ == '__main__':
    main()
